<script setup>
import { reactive } from 'vue';
const props = defineProps({ initialRepairment: { type: Object, default: () => ({}) }, busy: Boolean, submitLabel: { type: String, default: 'Save repairment' } });
const emit = defineEmits(['submit', 'cancel']);
const form = reactive({ status: props.initialRepairment.status || 'repairing', serial_num: props.initialRepairment.serial_num || '', field_test_date: (props.initialRepairment.field_test_date || []).join(', '), repairer: (props.initialRepairment.repairer || []).join(', '), spare_part: (props.initialRepairment.spare_part || []).map((p) => `${p.part}:${p.price}`).join(', '), update: '' });
function addToday() { const timestamp = new Date().toISOString(); form.field_test_date = [...form.field_test_date.split(',').map((v) => v.trim()).filter(Boolean), timestamp].join(', '); }
function submit() { if (!form.status) return; emit('submit', { status: form.status, serial_num: form.serial_num.trim(), field_test_date: form.field_test_date.split(',').map((v) => v.trim()).filter(Boolean), repairer: form.repairer.split(',').map((v) => v.trim()).filter(Boolean), spare_part: form.spare_part.split(',').map((v) => { const [part, price] = v.split(':'); return { part: part.trim(), price: Number(price) || 0 }; }).filter((v) => v.part), updates: form.update.trim() ? [{ text: form.update.trim() }] : undefined }); }
</script>
<template><form class="item-form" @submit.prevent="submit"><section class="form-section"><span class="eyebrow">Repairment record</span><h2>Track this unit’s repair</h2><div class="field-grid"><label class="field"><span>Serial number</span><input v-model="form.serial_num" name="serial_num" placeholder="SN-2026-001"></label><label class="field"><span>Status *</span><select v-model="form.status" name="status" required><option value="repairing">Repairing</option><option value="awaiting_spare_part">Awaiting spare part</option><option value="repaired">Repaired</option><option value="unrepairable">Unrepairable</option></select></label></div><label class="field"><span>Field test dates <em>comma separated</em></span><div class="input-with-action"><input v-model="form.field_test_date" name="field_test_date" placeholder="2026-09-08T10:30:00Z, 2026-09-12T14:00:00Z"><button type="button" class="button button--ghost" @click="addToday">Add today</button></div></label><label class="field"><span>Repairers <em>comma separated</em></span><input v-model="form.repairer" name="repairer" placeholder="Amina, Karim"></label><label class="field"><span>Spare parts <em>part:price, comma separated</em></span><input v-model="form.spare_part" name="spare_part" placeholder="Voltage regulator:12.50, Fuse:2"></label><label class="field"><span>Add update note</span><textarea v-model="form.update" name="update" rows="3" placeholder="Replaced the damaged regulator"></textarea></label></section><div class="form-actions"><button v-if="$attrs.onCancel" type="button" class="button button--ghost" @click="$emit('cancel')">Cancel</button><button class="button button--primary" :disabled="busy">{{ busy ? 'Saving…' : submitLabel }}</button></div></form></template>
